/**
 * The schema aggregate is up to date
 * ============================================================================
 *
 * `apps/api/src/db/schema-kons.generated.ts` is generated by
 * `scripts/sync-kon-schema.ts`, and for a while it was neither versioned nor
 * ignored: it existed only on the disk of whoever had generated it. Two
 * consequences, both verified:
 *
 *   - In a clean clone the file is not there, and `schema-all.ts` imports it with
 *     a hard `export *`. `tsc --noEmit` of apps/api fails with TS2307 — which is
 *     exactly what the CI typecheck job runs.
 *   - In existing clones it drifted silently. And it had drifted: it was
 *     missing kon-broadcast, kon-broadcast-moba, kon-ecommerce and kon-members.
 *
 * That last one was not cosmetic. The migration runner only reads
 * `apps/api/drizzle/` and `src/db/migrations/`, and the kons' own migrations
 * are applied by nobody (`runKonMigrations` has no callers and also looks for an
 * `init.sql` that none uses). This aggregate is the ONLY path
 * by which a kon's tables reach drizzle-kit and from there the
 * database. A kon that falls out of here is a kon whose tables are not created.
 *
 * Now the file is in git. This test is what keeps it from lying again: it
 * regenerates in memory and compares. It does NOT write — a test that fixed the
 * drift instead of reporting it would be useless.
 */

import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import { GENERATED, generateAggregate } from "../../apps/api/scripts/sync-kon-schema";

const ROOT = join(__dirname, "..", "..");

describe("schema-kons.generated.ts", () => {
  it("exists in the working tree", () => {
    // If this fails in CI, the file did not make it into the commit: `schema-all.ts` does not
    // resolve and the apps/api typecheck falls over entirely.
    expect(existsSync(GENERATED)).toBe(true);
  });

  it("matches what the generator produces", async () => {
    const { content } = await generateAggregate();
    // The generator writes LF; git may check the file out with CRLF. Same content.
    const onDisk = readFileSync(GENERATED, "utf8").replaceAll("\r\n", "\n");

    expect(
      onDisk,
      "The aggregate does not match its sources. Someone touched the `schema` of a " +
        "kon.json (or its schema file) without regenerating. Run:\n" +
        "  bun run apps/api/scripts/sync-kon-schema.ts"
    ).toBe(content);
  });

  it("includes all the kons that declare themselves drizzle-managed", async () => {
    // The check above would pass just the same if the generator stopped
    // finding kons: it would compare two empty files. This one looks at the sources.
    const konsDrizzle: string[] = [];
    // Only the core: installed kons create their tables with their own migrations.
    for (const tier of ["core"]) {
      const base = join(ROOT, "packages", tier);
      if (!existsSync(base)) continue;
      for (const dir of subdirectories(base)) {
        const manifest = join(base, dir, "kon.json");
        if (!existsSync(manifest)) continue;
        const m = JSON.parse(readFileSync(manifest, "utf8"));
        if (m.schema?.strategy === "drizzle" && m.schema?.entry) konsDrizzle.push(m.id ?? dir);
      }
    }

    const onDisk = readFileSync(GENERATED, "utf8");
    const absent = konsDrizzle.filter((id) => !onDisk.includes(`── ${id} ──`));

    expect(
      absent,
      `They declare strategy "drizzle" but are not in the aggregate, so their ` +
        `tables do not reach drizzle-kit and NOBODY creates them: ${absent.join(", ")}`
    ).toEqual([]);
    expect(konsDrizzle.length).toBeGreaterThanOrEqual(2);
  });

  it("re-exports schema-core before the kons", async () => {
    // The order is what resolves collisions: the explicit `export {}` of
    // an authoritative kon beats core's `export *` only if it goes after.
    const { content } = await generateAggregate();
    const posCore = content.indexOf('export * from "./schema-core"');
    const posFirstKon = content.indexOf("── kon-");

    expect(posCore).toBeGreaterThan(-1);
    expect(posFirstKon).toBeGreaterThan(posCore);
  });

  it("does not emit the same symbol twice", async () => {
    // Two `export { x }` in the same module are a TypeScript error. The
    // generator avoids it by omitting the second; this checks that it does.
    const { content } = await generateAggregate();
    const symbols = [...content.matchAll(/^\s{2}([A-Za-z_$][\w$]*),$/gm)].map((m) => m[1]);
    const seen = new Set<string>();
    const repeatedValues = symbols.filter((s) => (seen.has(s) ? true : (seen.add(s), false)));

    expect(repeatedValues).toEqual([]);
  });
});

function subdirectories(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name);
}
